from itertools import product

def three(c):
 d=2**c
 ws={0,d}
 for a in range(-1,c+1):
  A=0 if a<0 else 2**a
  ws.add(2*d-2*A)
 # all triples nonempty, common dim h
 for a,b,e in product(range(c+1),repeat=3):
  for h in range(min(a,b,e)+1):
   if max(a+b-h,a+e-h,b+e-h)<=c:
    ws.add(3*d-2*(2**a+2**b+2**e)+4*2**h)
   if max(a+b-h,a+e-h,b+e-h)<=c-1:
    ws.add(3*d-2*(2**a+2**b+2**e))
 for a,b in product(range(-1,c),repeat=2):
  A=0 if a<0 else 2**a; B=0 if b<0 else 2**b
  ws.add(3*d-2*(A+B))
 return ws
for c in range(3,8):
 ws=three(c)
 print(c,sorted(w for w in ws if 0<=w<5*2**(c-1)))
 print('missing',sorted(set(range(2**(c+1),5*2**(c-1),2))-ws))

