def coords(n):
 full=(1<<(1<<n))-1;co=[]
 for i in range(n):
  b=(1<<(1<<i))-1;z=0
  for j in range(1<<i,1<<n,2<<i):z|=b<<j
  co.append(z)
 return full,co

def mono(n,r):
 full,co=coords(n)
 return {sum(1<<i for i in ss):functools.reduce(int.__and__,(co[i] for i in ss),full) for ss in itertools.combinations(range(n),r)}
W=mono(6,3);l=list(W.items());R={}
for k in range(1,5):
 for cm in itertools.combinations(W,k):
  v=functools.reduce(int.__xor__,(W[x] for x in cm),0);R.setdefault(v.bit_count(),v)
