for s in range(1<<20):
 if s:bit=(s&-s).bit_length()-1;v^=l[bit][1]
 d=v.bit_count()
 for b,B in R.items():
  j=(v&B).bit_count()
  if j%2:P.setdefault((b,d,j),(B,v))
print('statesB',len(P),'seconds',time.time()-t,flush=True)
